 fields=['study_id','DOI','species','element','BCF_value','eligibility_status','exclusion_reason','source_reference']; w=csv.DictWriter(f,fieldnames=fields); w.writeheader()
 for p,sid,doi,title,sp,st,ct,fg,ts,ba,bd,ind,shared,notes in cands:
  if st!='INCLUDED': w.writerow({'study_id':sid,'DOI':doi,'species':sp,'element':'','BCF_value':'','eligibility_status':st,'exclusion_reason':notes,'source_reference':'verification_'+p+'_'+sid+'.md'})
