 for r in rows: w.writerow({'study_id':r['study_id'],'DOI':r['doi'],'source_document':r['source_reference'],'source_location':r['data_source_location'],'extraction_status':r['directly_reported_or_digitized'],'verification_status':r['verification_status']})
